
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_br89_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_br89", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.417190409390202e+00, -3.405278934162762e+00, -3.383404621569294e+00, -3.343522208715919e+00, -3.272223753504957e+00, -3.148946861849122e+00, -2.946081588793277e+00, -2.637149119075974e+00, -2.221136824238915e+00, -1.737952346931820e+00, -1.229511929910786e+00, -7.473792279943380e-01, -5.752458579679566e-01, -5.038177029424485e-01, -3.968119470991372e-01, -2.754903462850294e-01, -1.796193303464242e-01, -1.163144211176865e-01, -7.676652606241532e-02, -5.158538111871178e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


